/// <summary>
/// Creates a collector for image capture steps: gif, jpg and png are supported
/// </summary>
/// <param name="_id"></param>
/// <param name="_name"></param>
/// <param name="_label"></param>
/// <param name="_header"></param>
/// <param name="_defaultValue">
/// foler to store the image in
/// </param>
/// <param name="_resolutionHeight"></param>
/// <param name="_resolutionWidth"></param>
/// <param name="_listSeparator">
/// seperator between filename (name) and comment)
/// </param>
server static Map ImageCaptureStepMap(
                                                int _id,
                                                str _name,
                                                str _label,
                                                str _header,
                                                str _defaultValue,                                                  
                                                str _listSeparator = ';')
{
    Map stepMap = new Map(Types::String, Types::String);

    stepMap.insert(TFMConstants::AttributeId(),int2str(_id));
    stepMap.insert(TFMConstants::AttributeName(),_name);
    stepMap.insert(TFMConstants::AttributeLabel(), _label);
    stepMap.insert(TFMConstants::AttributeInputType(),enum2Symbol(enumNum(TFMInputTypes),TFMInputTypes::ImageCapture));
    stepMap.insert(TFMConstants::AttributeHeader(),_header);
    stepMap.insert(TFMConstants::AttributeDefaultValue(),_defaultValue);
    stepMap.insert(TFMConstants::AttributeListSeparator(), _listSeparator);

    return stepMap;
}
